def semver_sort(versions):
    def parse_version(v):
        # Split into core version and optional pre-release and build metadata
        if '+' in v:
            core_and_pre, build = v.rsplit('+', 1)
        else:
            core_and_pre = v
            build = None

        if '-' in core_and_pre:
            core, prerelease = core_and_pre.split('-', 1)
        else:
            core = core_and_pre
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_parts = prerelease.split('.')
            pre_parsed = []
            for part in prerelease_parts:
                if part.isdigit():
                    pre_parsed.append((0, int(part)))
                else:
                    pre_parsed.append((1, part))
        else:
            pre_parsed = None

        return (major, minor, patch, pre_parsed)

    def sort_key(item):
        index, version = item
        major, minor, patch, pre_parsed = parse_version(version)

        # Pre-release versions sort before release versions
        if pre_parsed is None:
            pre_sort_key = (1,)  # No pre-release sorts after pre-release
        else:
            pre_sort_key = (0, pre_parsed)  # Pre-release sorts first

        return (major, minor, patch, pre_sort_key, index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

